<script setup>
import { computed } from 'vue';
import { ArrowLeft, Download, Printer } from 'lucide-vue-next';
import { useRoute, useRouter } from 'vue-router';
import { useInvoiceStore } from '@/stores/invoice';
import { masterDataConfig } from '@/data/masterDataMock';
import { formatCurrency, formatDate } from '@/utils/formatters';
import BaseButton from '@/components/ui/BaseButton.vue';
const route=useRoute(),router=useRouter(),store=useInvoiceStore();
const invoice=computed(()=>store.previewInvoice?.id===route.params.id?store.previewInvoice:store.getInvoiceById(route.params.id));
const account=computed(()=>masterDataConfig.account.records.find(x=>x.id===invoice.value?.accountId));
const client=computed(()=>masterDataConfig.client.records.find(x=>x.id===invoice.value?.clientId));
const total=computed(()=>invoice.value?.items.reduce((sum,item)=>sum+item.price*item.qty,0)-(invoice.value?.discount||0));
</script>
<template><main class="min-h-screen bg-[#E8ECF2]"><header class="invoice-toolbar sticky top-0 z-10 flex h-[52px] items-center justify-between border-b border-[#D8DEE8] bg-white px-5"><BaseButton size="sm" variant="ghost" @click="router.back()"><ArrowLeft :size="15"/>Kembali</BaseButton><div class="flex items-center gap-2"><BaseButton size="sm" variant="secondary" disabled title="PDF server-side belum diimplementasikan"><Download :size="15"/>Unduh PDF</BaseButton><BaseButton size="sm" @click="window.print()"><Printer :size="15"/>Cetak</BaseButton></div></header><section v-if="invoice" class="invoice-print-shell mx-auto max-w-[210mm] p-5 md:p-8"><article class="invoice-print relative min-h-[297mm] overflow-hidden bg-white px-[14mm] py-[13mm] text-[#172033] shadow-sm"><div class="pointer-events-none absolute inset-0 opacity-[0.055]" style="background-image:url('/images/invoice/bg-invoice.png');background-repeat:no-repeat;background-position:center;background-size:78%;"/><div class="relative"><div class="flex items-start justify-between border-b-2 border-[#173B6C] pb-6"><img :src="'/images/invoice/devspace-invoice-logo.png'" alt="DEVSPACE" class="h-11 w-auto object-contain"/><div class="text-right"><h1 class="text-[25px] font-bold tracking-[0.16em] text-[#173B6C]">INVOICE</h1><p class="mt-2 text-[12px] text-[#667085]">{{invoice.number}}</p></div></div><div class="grid grid-cols-2 gap-10 py-7 text-[12px]"><div><p class="mb-2 font-semibold uppercase tracking-wide text-[#173B6C]">Ditagihkan kepada</p><p class="text-[14px] font-semibold">{{invoice.client}}</p><p class="mt-1 leading-5 text-[#667085]">{{client?.alamat||'-'}}<br/>{{client?.email||''}}</p></div><div class="text-right"><p><span class="text-[#667085]">Tanggal Invoice:</span> <strong>{{formatDate(invoice.date)}}</strong></p><p class="mt-2"><span class="text-[#667085]">Jatuh Tempo:</span> <strong>{{formatDate(invoice.dueDate)}}</strong></p></div></div><table class="w-full border-collapse text-[12px]"><thead class="bg-[#173B6C] text-white"><tr><th class="px-3 py-3 text-left font-medium">Deskripsi</th><th class="w-20 px-3 py-3 text-center font-medium">Qty</th><th class="w-28 px-3 py-3 text-right font-medium">Harga</th><th class="w-32 px-3 py-3 text-right font-medium">Total</th></tr></thead><tbody><tr v-for="item in invoice.items" :key="item.id" class="border-b border-[#E2E6EC]"><td class="px-3 py-3"><p class="font-medium">{{item.product||item.description}}</p><p v-if="item.product" class="mt-0.5 text-[#667085]">{{item.description}}</p></td><td class="px-3 py-3 text-center">{{item.qty}}</td><td class="px-3 py-3 text-right">{{formatCurrency(item.price)}}</td><td class="px-3 py-3 text-right font-medium">{{formatCurrency(item.price*item.qty)}}</td></tr></tbody></table><div class="ml-auto mt-5 w-[285px] text-[12px]"><div class="flex justify-between py-1.5 text-[#667085]"><span>Subtotal</span><span>{{formatCurrency(total+invoice.discount)}}</span></div><div class="flex justify-between py-1.5 text-[#667085]"><span>Diskon</span><span>{{formatCurrency(invoice.discount)}}</span></div><div class="mt-2 flex justify-between border-t-2 border-[#173B6C] py-3 text-[15px] font-bold text-[#173B6C]"><span>TOTAL</span><span>{{formatCurrency(total)}}</span></div></div><div class="mt-9 grid grid-cols-2 gap-10 text-[12px]"><div><p class="font-semibold text-[#173B6C]">Pembayaran</p><p class="mt-2 leading-5 text-[#667085]">{{account?.nama||'-'}}<br/>{{account?.nomor||'-'}}<br/>a.n. {{account?.atasNama||'-'}}</p></div><div><p class="font-semibold text-[#173B6C]">Syarat & Ketentuan</p><p class="mt-2 leading-5 text-[#667085]">{{invoice.terms||'Silakan lakukan pembayaran sesuai informasi rekening di atas.'}}</p></div></div><div class="mt-12 flex justify-end"><div class="w-40 text-center text-[12px]"><div class="mx-auto mb-2 flex h-14 w-14 items-center justify-center rounded-full border-2 border-[#D4A72C] text-[9px] font-semibold text-[#B8860B]">DEVSPACE<br/>DEMO</div><p class="border-t border-[#667085] pt-1">Ruang Kreasi Aplikasi</p></div></div></div></article></section><section v-else class="p-8 text-center text-sm text-[#667085]">Data preview tidak tersedia. Kembali ke daftar Invoice lalu pilih Preview.</section></main></template>
<style>
@media print { .invoice-toolbar { display: none !important; } .invoice-print-shell { max-width: none !important; padding: 0 !important; } .invoice-print { box-shadow: none !important; min-height: 297mm !important; } }
</style>
